package ru.neverland.townyquests;
import java.util.*;import org.bukkit.configuration.file.YamlConfiguration;
import ru.neverland.townyquests.config.*;import ru.neverland.townyquests.model.*;
public final class ProjectBranchesSmoke {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}public static void main(String[] args)throws Exception{var c=new YamlConfiguration();var q=new YamlConfiguration();try(var in=ProjectBranchesSmoke.class.getResourceAsStream("/config.yml")){c.load(new java.io.InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8));}try(var in=ProjectBranchesSmoke.class.getResourceAsStream("/quests.yml")){q.load(new java.io.InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8));}var s=QuestSettings.load(c,q);var green=s.projects().get("green_future");var industry=s.projects().get("industrial_future");check(green.choiceGroup().equals(industry.choiceGroup())&&!green.unlock().equals(industry.unlock()),"exclusive branches yield different rewards");var selected=CityProject.start(green).control("cancel");check(ProjectBranches.alternative(industry,List.of(selected)).isPresent(),"cancellation preserves choice");check(ProjectBranches.alternative(green,List.of(selected)).isEmpty(),"same branch can resume");check(ProjectBranches.alternative(s.projects().get("sanitation"),List.of(selected)).isEmpty(),"legacy chain remains independent");ProjectBranches.validate(List.of(selected));try{ProjectBranches.validate(List.of(selected,CityProject.start(industry)));throw new AssertionError("conflicting persisted choices");}catch(IllegalArgumentException expected){}var encoded=new YamlConfiguration();QuestSettings.writeProject(encoded,green);var saved=QuestSettings.project(green.id(),encoded);check(saved.choiceGroup().equals(green.choiceGroup()),"choice persists with project snapshot");System.out.println("ProjectBranchesSmoke PASS: alternative rewards, neutral cancellation, old chains and conflicting-history rejection");}
}
